<script setup>
import {ref,computed,onMounted} from 'vue';import {ShoppingBag,Search,LayoutDashboard,UtensilsCrossed,ClipboardList,Users,Bell,LogOut,UserRound,Plus,Trash2,ChartColumnIncreasing,Leaf,Menu,ImagePlus,ArrowRight,CheckCircle,LockKeyhole} from 'lucide-vue-next';
const token=ref(sessionStorage.getItem('fh_token')||''),user=ref(JSON.parse(sessionStorage.getItem('fh_user')||'null')),page=ref('home'),foods=ref([]),categories=ref([]),cart=ref([]),orders=ref([]),notifications=ref([]),users=ref([]),metrics=ref({}),allOrders=ref([]),search=ref(''),category=ref('All'),error=ref(''),success=ref(''),busy=ref(false),loginMode=ref('login'),auth=ref({full_name:'',username:'',email:'',phone:'',password:'',login:'',role:'customer',admin_code:''}),foodForm=ref({name:'',category_id:1,description:'',price_minor:0,stock:10}),editing=ref(null),imageFile=ref(null),profile=ref({full_name:'',phone:''}),passwords=ref({current:'',password:''});
const isAdmin=computed(()=>user.value?.role==='admin');const filtered=computed(()=>foods.value.filter(f=>(category.value==='All'||f.category===category.value)&&f.name.toLowerCase().includes(search.value.toLowerCase())));const cartTotal=computed(()=>cart.value.reduce((s,x)=>s+x.line_minor,0));const money=n=>'LKR '+(Number(n||0)/100).toLocaleString('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2});
async function api(path,method='GET',body=null,raw=false){let h={};if(token.value)h.Authorization='Bearer '+token.value;if(body&&!raw)h['Content-Type']='application/json';if(raw)h['Content-Type']=raw;let r=await fetch('/api'+path,{method,headers:h,body:body?(raw?body:JSON.stringify(body)):undefined});let j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
async function run(fn){error.value='';success.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function refresh(){foods.value=await api('/foods');categories.value=await api('/categories');if(token.value){const a=await api('/auth/me');if(!a.length){logout();return}profile.value={full_name:a[0].full_name,phone:a[0].phone};notifications.value=await api('/notifications');if(isAdmin.value){metrics.value=await api('/admin/analytics');allOrders.value=await api('/admin/orders');users.value=await api('/admin/users')}else{cart.value=await api('/cart');orders.value=await api('/orders')}}}
async function sign(){await run(async()=>{if(loginMode.value==='register'){await api('/auth/register','POST',auth.value);success.value='Account created. Sign in to continue.';loginMode.value='login'}else{const d=await api('/auth/login','POST',auth.value);token.value=d.token;user.value={id:d.id,name:d.name,role:d.role};sessionStorage.setItem('fh_token',d.token);sessionStorage.setItem('fh_user',JSON.stringify(user.value));page.value=isAdmin.value?'dashboard':'home';await refresh()}})}
async function logout(){try{if(token.value)await api('/auth/logout','POST')}catch{}token.value='';user.value=null;sessionStorage.removeItem('fh_token');sessionStorage.removeItem('fh_user');page.value='home';cart.value=[]}
function goMenu(){document.getElementById('menu')?.scrollIntoView({behavior:'smooth'})}
function nav(p){page.value=p;error.value='';success.value='';if(token.value)refresh().catch(e=>error.value=e.message)}
async function qty(id,q){await run(async()=>{await api('/cart/'+id,'PUT',{qty:q});cart.value=await api('/cart');success.value='Cart updated'})}
async function checkout(){if(!confirm('Place this order?'))return;await run(async()=>{let x=await api('/orders','POST',{});success.value='Order #'+x.id+' placed successfully!';cart.value=[];page.value='orders';await refresh()})}
async function saveFood(){await run(async()=>{const payload={...foodForm.value,price_minor:Math.round(Number(foodForm.value.price_minor))};const result=await api(editing.value?'/admin/foods/'+editing.value:'/admin/foods',editing.value?'PUT':'POST',payload);const id=editing.value||result.id;if(imageFile.value){const file=imageFile.value;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('PNG, JPEG or WebP required');await api('/admin/foods/'+id+'/image','POST',file,file.type)}editing.value=null;imageFile.value=null;foodForm.value={name:'',category_id:categories.value[0]?.id||1,description:'',price_minor:0,stock:10};success.value='Food saved successfully';await refresh()})}
function editFood(f){editing.value=f.id;foodForm.value={name:f.name,category_id:f.category_id,description:f.description,price_minor:f.price_minor,stock:f.stock};page.value='manage-food'}
async function deleteFood(id){if(!confirm('Deactivate this food?'))return;await run(async()=>{await api('/admin/foods/'+id,'DELETE');await refresh()})}
async function status(id,value){await run(async()=>{await api('/admin/orders/'+id+'/status','PUT',{status:value});await refresh()})}
async function active(id,value){await run(async()=>{await api('/admin/users/'+id+'/active','PUT',{active:value});await refresh()})}
async function updateProfile(){await run(async()=>{await api('/profile','PUT',profile.value);success.value='Profile updated';await refresh()})}
async function changePassword(){await run(async()=>{await api('/auth/password','POST',passwords.value);passwords.value={current:'',password:''};success.value='Password changed'})}
async function readNotifications(){await run(async()=>{await api('/notifications/read','POST',{});await refresh()})}
onMounted(()=>refresh().catch(e=>error.value=e.message));
</script>
<template>
<div class="app">
<header class="topbar"><div class="shell header"><a class="brand" @click="nav(isAdmin?'dashboard':'home')"><span class="brand-icon"><UtensilsCrossed :size="23"/></span><span>food<span class="green">hub</span><small>FRESHLY MADE, JUST FOR YOU</small></span></a><nav v-if="user" class="nav"><button v-for="x in (isAdmin?[['dashboard','Dashboard'],['manage-food','Food Items'],['admin-orders','Orders'],['users','Users']]:[['home','Explore Menu'],['cart','My Cart'],['orders','My Orders']])" :key="x[0]" @click="nav(x[0])" :class="{selected:page===x[0]}">{{x[1]}}</button></nav><div class="header-actions"><button v-if="user" class="iconbtn" @click="nav('notifications')"><Bell :size="20"/><i v-if="notifications.some(x=>!x.is_read)" class="dot"></i></button><button v-if="user" class="iconbtn" @click="nav('profile')"><UserRound :size="20"/></button><button v-if="user" class="iconbtn" title="Log out" @click="logout"><LogOut :size="20"/></button><button v-else class="btn" @click="page='auth'">Sign in <ArrowRight :size="16"/></button></div></div></header>
<main class="shell"><div v-if="error" class="alert error">{{error}} <button @click="error=''">×</button></div><div v-if="success" class="alert success">{{success}} <button @click="success=''">×</button></div>
<section v-if="page==='auth' || !user" class="auth-layout"><div class="auth-intro"><span class="eyebrow">GOOD FOOD. GOOD MOOD.</span><h1>Your next favorite meal starts <em>here.</em></h1><p>Fresh flavors, delightful choices, and easy ordering. Welcome to a better way to enjoy food.</p><div class="auth-visual"><span>🥗</span><span>🍔</span><span>🥑</span></div></div><div class="auth-card"><div class="tabs"><button :class="{active:loginMode==='login'}" @click="loginMode='login'">Sign In</button><button :class="{active:loginMode==='register'}" @click="loginMode='register'">Create Account</button></div><h2>{{loginMode==='login'?'Welcome back':'Join FoodHub'}}</h2><p class="muted">{{loginMode==='login'?'Sign in to continue your food journey':'Create your account to get started'}}</p><form @submit.prevent="sign" class="form"><template v-if="loginMode==='register'"><label>Full name<input v-model="auth.full_name" required placeholder="Your full name"/></label><label>Username<input v-model="auth.username" required minlength="3" placeholder="Choose a username"/></label><label>Email address<input v-model="auth.email" type="email" required placeholder="you@example.com"/></label><label>Phone number<input v-model="auth.phone" placeholder="Phone number"/></label><label>Account type<select v-model="auth.role"><option value="customer">Customer</option><option value="admin">Administrator</option></select></label><label v-if="auth.role==='admin'">Administrator security code<input v-model="auth.admin_code" type="password" required placeholder="Enter admin access code"/></label></template><label v-if="loginMode==='login'">Username or email<input v-model="auth.login" required placeholder="Enter username or email"/></label><label>Password<input v-model="auth.password" type="password" minlength="8" required placeholder="Enter your password"/></label><button class="btn wide" :disabled="busy">{{loginMode==='login'?'Sign In':'Create Account'}} <ArrowRight :size="17"/></button></form></div></section>
<template v-else-if="!isAdmin">
<section v-if="page==='home'" class="hero"><div class="hero-copy"><span class="eyebrow">✦ FRESH FOOD, EVERY DAY</span><h1>Delicious food,<br/><em>delivered with love.</em></h1><p>Discover freshly prepared favorites, choose what you love, and enjoy a simple ordering experience.</p><button class="btn" @click="goMenu">Explore our menu <ArrowRight :size="18"/></button><div class="hero-stats"><span><strong>{{foods.length}}+</strong><small>Menu items</small></span><span><strong>Fresh</strong><small>Every day</small></span><span><strong>Easy</strong><small>Ordering</small></span></div></div><div class="hero-art"><div class="circle-food">🥗</div><span class="float f1">🥑</span><span class="float f2">🍅</span><span class="float f3">🥬</span><div class="fresh-tag">✦ Fresh & tasty</div></div></section>
<section v-if="page==='home'" id="menu" class="section"><div class="section-title"><div><span class="eyebrow">MADE FOR YOUR CRAVINGS</span><h2>Explore our <em>menu</em></h2></div><span class="muted">{{filtered.length}} delicious choices</span></div><div class="filters"><div class="search"><Search :size="19"/><input v-model="search" placeholder="Search delicious food..."/></div><div class="chips"><button v-for="c in ['All',...categories.map(x=>x.name)]" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</button></div></div><div class="food-grid"><article v-for="f in filtered" :key="f.id" class="food-card"><div class="food-image"><img v-if="f.image_path" :src="f.image_path" :alt="f.name"/><span v-else>🍽️</span><span class="category-tag">{{f.category}}</span></div><div class="food-body"><h3>{{f.name}}</h3><p>{{f.description||'Freshly prepared and full of flavor.'}}</p><div class="food-footer"><strong>{{money(f.price_minor)}}</strong><button class="addbtn" :disabled="f.stock<1" @click="qty(f.id,(cart.find(x=>x.id===f.id)?.qty||0)+1)"><Plus :size="19"/></button></div><small class="muted">{{f.stock>0?f.stock+' available':'Sold out'}}</small></div></article></div><div v-if="!filtered.length" class="empty">No food items found. Check back soon!</div></section>
<section v-if="page==='cart'" class="section"><div class="section-title"><div><span class="eyebrow">YOUR SELECTION</span><h2>Shopping <em>cart</em></h2></div></div><div class="two-col"><div class="panel"><div v-for="c in cart" :key="c.id" class="cart-row"><div class="thumb"><img v-if="c.image_path" :src="c.image_path"/> <span v-else>🍽️</span></div><div class="grow"><strong>{{c.name}}</strong><p class="muted">{{money(c.price_minor)}} each</p></div><div class="stepper"><button @click="qty(c.id,c.qty-1)">−</button><b>{{c.qty}}</b><button @click="qty(c.id,c.qty+1)">+</button></div><strong>{{money(c.line_minor)}}</strong><button class="iconbtn" @click="qty(c.id,0)"><Trash2 :size="18"/></button></div><div v-if="!cart.length" class="empty">Your cart is empty. Add something delicious!</div></div><div class="panel summary"><h3>Order Summary</h3><div class="summary-line"><span>Subtotal</span><b>{{money(cartTotal)}}</b></div><div class="summary-line"><span>Delivery</span><b>Not included</b></div><hr/><div class="summary-line total"><span>Total</span><b>{{money(cartTotal)}}</b></div><button class="btn wide" :disabled="!cart.length||busy" @click="checkout">Place Order <ArrowRight :size="18"/></button><p class="muted tiny">Demo checkout · Payment remains unpaid until confirmed separately.</p></div></div></section>
<section v-if="page==='orders'" class="section"><div class="section-title"><div><span class="eyebrow">YOUR FOOD JOURNEY</span><h2>Order <em>history</em></h2></div></div><div class="panel"><div v-for="o in orders" :key="o.id" class="order-row"><div><strong>Order #{{o.id}}</strong><p class="muted">{{o.created_at}}</p></div><span class="pill">{{o.status}}</span><span class="muted">{{o.payment_status}}</span><strong>{{money(o.total_minor)}}</strong><button class="textbtn" @click="run(async()=>{let d=await api('/orders/'+o.id);alert(d.map(x=>x.food_name+' × '+x.qty+' — '+money(x.unit_price_minor*x.qty)).join('\n'))})">View items →</button></div><div v-if="!orders.length" class="empty">You haven't placed any orders yet.</div></div></section>
</template>
<template v-else><section v-if="page==='dashboard'" class="section"><div class="section-title"><div><span class="eyebrow">MANAGEMENT OVERVIEW</span><h2>Admin <em>dashboard</em></h2></div><button class="btn" @click="nav('manage-food')"><Plus :size="17"/> Add food item</button></div><div class="stats-grid"><div class="stat"><span>Customers</span><strong>{{metrics.customers||0}}</strong><Users/></div><div class="stat"><span>Food Items</span><strong>{{metrics.foods||0}}</strong><UtensilsCrossed/></div><div class="stat"><span>Total Orders</span><strong>{{metrics.orders||0}}</strong><ShoppingBag/></div><div class="stat"><span>Completed Order Value</span><strong>{{money(metrics.completed_value_minor)}}</strong><ChartColumnIncreasing/></div></div><div class="panel"><h3>Monthly orders & completed order value</h3><div v-if="metrics.monthly?.length" class="chart"><div v-for="m in metrics.monthly" :key="m.month" class="chart-col"><div class="bar" :style="{height:Math.max(8,m.count/Math.max(1,...metrics.monthly.map(x=>x.count))*180)+'px'}"></div><small>{{m.month}}</small><b>{{m.count}}</b></div></div><div v-else class="empty">Charts will appear after customers place orders.</div></div></section>
<section v-if="page==='manage-food'" class="section"><div class="section-title"><div><span class="eyebrow">MENU MANAGEMENT</span><h2>Manage <em>food items</em></h2></div></div><div class="two-col admin-layout"><form class="panel form" @submit.prevent="saveFood"><h3>{{editing?'Edit Food Item':'Add New Food Item'}}</h3><label>Food name<input v-model="foodForm.name" required placeholder="e.g. Chicken Fried Rice"/></label><label>Category<select v-model.number="foodForm.category_id"><option v-for="c in categories" :value="c.id">{{c.name}}</option></select></label><label>Description<textarea v-model="foodForm.description" rows="3" placeholder="Describe this delicious dish"></textarea></label><label>Price (LKR)<input type="number" min="0" step="0.01" :value="foodForm.price_minor/100" @input="foodForm.price_minor=Math.round(Number($event.target.value)*100)" required/></label><label>Available quantity<input v-model.number="foodForm.stock" type="number" min="0" required/></label><label class="upload"><ImagePlus :size="25"/><span>Choose food image (PNG / JPG / WebP)</span><small>Recommended square 1:1 image, up to 5 MB</small><input type="file" accept="image/png,image/jpeg,image/webp" @change="imageFile=$event.target.files[0]"/></label><span v-if="imageFile" class="muted">Selected: {{imageFile.name}}</span><button class="btn wide" :disabled="busy">{{editing?'Save Changes':'Add Food Item'}}</button><button v-if="editing" type="button" class="textbtn" @click="editing=null;foodForm={name:'',category_id:1,description:'',price_minor:0,stock:10}">Cancel edit</button></form><div class="panel"><h3>Current Menu ({{foods.length}})</h3><div v-for="f in foods" :key="f.id" class="manage-row"><div class="thumb"><img v-if="f.image_path" :src="f.image_path"/><span v-else>🍽️</span></div><div class="grow"><strong>{{f.name}}</strong><p class="muted">{{money(f.price_minor)}} · Stock {{f.stock}}</p></div><button class="textbtn" @click="editFood(f)">Edit</button><button class="iconbtn" @click="deleteFood(f.id)"><Trash2 :size="17"/></button></div><div v-if="!foods.length" class="empty">Add your first food item using the form.</div></div></div></section>
<section v-if="page==='admin-orders'" class="section"><div class="section-title"><div><span class="eyebrow">FULFILLMENT</span><h2>Manage <em>orders</em></h2></div></div><div class="panel"><div v-for="o in allOrders" :key="o.id" class="order-row"><div><strong>#{{o.id}} · {{o.customer}}</strong><p class="muted">{{o.created_at}}</p></div><strong>{{money(o.total_minor)}}</strong><span class="muted">{{o.payment_status}}</span><select :value="o.status" @change="status(o.id,$event.target.value)" :disabled="['Completed','Cancelled'].includes(o.status)"><option v-for="s in ['Pending','Confirmed','Preparing','Ready','Completed','Cancelled']">{{s}}</option></select></div><div v-if="!allOrders.length" class="empty">No orders yet.</div></div></section>
<section v-if="page==='users'" class="section"><div class="section-title"><div><span class="eyebrow">ACCOUNT CONTROL</span><h2>Manage <em>users</em></h2></div></div><div class="panel"><div v-for="u in users" :key="u.id" class="order-row"><div><strong>{{u.full_name}}</strong><p class="muted">{{u.email}} · @{{u.username}}</p></div><span class="pill">{{u.role}}</span><span>{{u.active?'Active':'Disabled'}}</span><button class="textbtn" @click="active(u.id,u.active?0:1)">{{u.active?'Disable':'Enable'}}</button></div></div></section></template>
<section v-if="user&&page==='notifications'" class="section narrow"><div class="section-title"><div><span class="eyebrow">STAY IN THE LOOP</span><h2>Your <em>notifications</em></h2></div><button class="textbtn" @click="readNotifications">Mark all as read</button></div><div class="panel"><div v-for="n in notifications" :key="n.id" class="notification" :class="{unread:!n.is_read}"><span class="notice-icon"><Bell :size="18"/></span><div><strong>{{n.title}}</strong><p>{{n.message}}</p><small class="muted">{{n.created_at}}</small></div></div><div v-if="!notifications.length" class="empty">No notifications yet.</div></div></section>
<section v-if="user&&page==='profile'" class="section narrow"><div class="section-title"><div><span class="eyebrow">PERSONAL SETTINGS</span><h2>My <em>profile</em></h2></div></div><div class="panel"><form class="form" @submit.prevent="updateProfile"><h3>Account details</h3><label>Full name<input v-model="profile.full_name" required/></label><label>Phone<input v-model="profile.phone"/></label><button class="btn">Save profile</button></form><hr/><form class="form" @submit.prevent="changePassword"><h3>Change password</h3><label>Current password<input v-model="passwords.current" type="password" required/></label><label>New password<input v-model="passwords.password" type="password" minlength="8" required/></label><button class="btn">Update password</button></form></div></section>
</main><footer class="footer"><div class="shell"><strong>food<span class="green">hub</span></strong><span>Fresh choices. Happy moments. © 2026 FoodHub.</span></div></footer></div>
</template>
